<?php
namespace Tests\Feature;
use App\Models\User;
use App\Services\{CadenceEmail,CadenceEmailTransport,VoiceFollowups,CadenceReentry};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Http,URL};
use Illuminate\Support\Str;
use Tests\TestCase;
class CadenceEmailTest extends TestCase {
 use RefreshDatabase;
 private User $admin;private int $campaign;private int $contact;
 protected function setUp():void {
  parent::setUp();Http::preventStrayRequests();$this->travelTo(now()->setDate(2026,10,18)->setTime(12,0));
  $this->admin=User::factory()->create();$this->admin->forceFill(['voice_workspace_id'=>1,'voice_role'=>'admin'])->save();$this->actingAs($this->admin);
  $s=['timezone'=>'UTC','days'=>[1,2,3,4,5,6,7],'start_time'=>'00:00','end_time'=>'23:59','max_attempts'=>2,'whatsapp_enabled'=>false,'retry_minutes'=>0];
  $this->campaign=DB::table('voice_campaigns')->insertGetId(['workspace_id'=>1,'name'=>'Campanha QA','status'=>'paused','settings'=>json_encode($s),'created_at'=>now(),'updated_at'=>now()]);
  $this->contact=DB::table('voice_contacts')->insertGetId(['workspace_id'=>1,'name'=>'Pessoa Teste','phone'=>'+5511999990001','original_phone'=>'+5511999990001','source'=>'QA','consent'=>true,'consent_evidence'=>'Teste autorizado','fields'=>json_encode(['email'=>'person@example.test'])]);DB::table('voice_members')->insert(['campaign_id'=>$this->campaign,'contact_id'=>$this->contact]);
 }
 private function endpoint():string{return '/api/voice/campaigns/'.$this->campaign.'/impact';}
 private function prepare(array $extra=[]):void{$this->putJson($this->endpoint(),$extra+['revision'=>0,'enabled'=>true,'subject'=>'Olá, {primeiro_nome}','body'=>'Podemos conversar, {nome}?','delay_minutes'=>0])->assertOk();DB::table('voice_campaigns')->where('id',$this->campaign)->update(['status'=>'testing']);$this->travel(1)->seconds();}
 private function attempt(array $extra=[]):string{$id=(string)Str::uuid();DB::table('voice_outbound_calls')->insert($extra+['id'=>$id,'workspace_id'=>1,'campaign_id'=>$this->campaign,'contact_id'=>$this->contact,'user_id'=>$this->admin->id,'idempotency_key'=>$id,'request_hash'=>hash('sha256',$id),'grant_hash'=>hash('sha256','grant'.$id),'configuration_hash'=>hash('sha256','config'),'max_seconds'=>30,'ring_seconds'=>15,'consent_evidence'=>'Test consent','grant_expires_at'=>now()->addMinute(),'deadline_at'=>now()->addMinute(),'method'=>'api','environment'=>'test','destination'=>'+5511999990001','caller_id'=>'+12025550123','status'=>'no_answer','campaign_revision'=>DB::table('voice_campaigns')->where('id',$this->campaign)->value('followup_revision'),'started_at'=>now()->subSeconds(10),'ended_at'=>now(),'capacity_released_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);app(VoiceFollowups::class)->observe($id);return $id;}
 private function pending():object{$this->attempt();$this->attempt();return DB::table('voice_email_followups')->firstOrFail();}
 private function transport(bool $ready=true,bool $fail=false,int $times=1):void{$m=\Mockery::mock(CadenceEmailTransport::class);$m->shouldReceive('ready')->andReturn($ready);if($times){$x=$m->shouldReceive('send')->times($times);if($fail)$x->andThrow(new \RuntimeException('private smtp details'));else $x->andReturnNull();}else $m->shouldNotReceive('send');$this->app->instance(CadenceEmailTransport::class,$m);}
 public function test_configuration_defaults_disabled_and_readiness_is_read_only():void{$this->getJson($this->endpoint())->assertOk()->assertJsonPath('email.enabled',false)->assertJsonPath('threshold',2)->assertJsonPath('transport.ready',false);$this->assertDatabaseCount('voice_email_settings',0);Http::assertNothingSent();}
 public function test_threshold_duplicate_callbacks_and_no_resubmission():void{$this->prepare();$this->attempt();$this->assertDatabaseCount('voice_email_followups',0);$last=$this->attempt();app(VoiceFollowups::class)->observe($last);$this->assertDatabaseCount('voice_email_followups',1);$f=DB::table('voice_email_followups')->first();$this->transport();app(CadenceEmail::class)->dispatch($f->id);app(CadenceEmail::class)->dispatch($f->id);$this->assertDatabaseHas('voice_email_followups',['id'=>$f->id,'status'=>'accepted']);$this->postJson($this->endpoint().'/email/'.$f->id.'/retry')->assertStatus(422);}
 public function test_ambiguous_smtp_failure_is_durable_and_secret_is_not_returned():void{$this->prepare();$f=$this->pending();$this->transport(true,true);app(CadenceEmail::class)->run();app(CadenceEmail::class)->run();$this->assertDatabaseHas('voice_email_followups',['id'=>$f->id,'status'=>'unknown']);$this->getJson($this->endpoint())->assertDontSee('private smtp details');$this->postJson($this->endpoint().'/email/'.$f->id.'/retry')->assertStatus(422);}
 public function test_pause_and_daily_budget_hold_without_submitting():void{$this->prepare();$f=$this->pending();$this->transport(true,false,0);DB::table('voice_campaigns')->where('id',$this->campaign)->update(['status'=>'paused']);app(CadenceEmail::class)->run();$this->assertDatabaseHas('voice_email_followups',['status'=>'pending','submitted_at'=>null]);DB::table('voice_campaigns')->where('id',$this->campaign)->update(['status'=>'testing']);config(['cadence_email.daily_limit'=>0]);app(CadenceEmail::class)->run();$this->assertDatabaseHas('voice_email_followups',['status'=>'pending','submitted_at'=>null]);}
 public function test_missing_transport_can_be_rechecked_but_never_replays_old_calls():void{$this->attempt();$this->attempt();$this->prepare();$this->assertDatabaseCount('voice_email_followups',0);$this->attempt();$this->assertDatabaseCount('voice_email_followups',0);$this->attempt();$f=DB::table('voice_email_followups')->firstOrFail();$this->transport(false,false,0);app(CadenceEmail::class)->run();$this->assertDatabaseHas('voice_email_followups',['status'=>'blocked','submitted_at'=>null]);$this->postJson($this->endpoint().'/email/'.$f->id.'/retry')->assertOk();$this->assertDatabaseHas('voice_email_followups',['status'=>'pending']);}
 public function test_reply_or_optout_prevents_pending_send():void{$this->prepare();$f=$this->pending();$this->transport(true,false,0);DB::table('voice_contacts')->where('id',$this->contact)->update(['replied_at'=>now()]);app(CadenceEmail::class)->run();$this->assertDatabaseHas('voice_email_followups',['status'=>'cancelled']);}
 public function test_human_answer_cancels_pending_email():void{$this->prepare();$f=$this->pending();$this->attempt(['status'=>'completed','answered_at'=>now()]);$this->assertDatabaseHas('voice_email_followups',['id'=>$f->id,'status'=>'cancelled']);}
 public function test_changed_address_or_removed_membership_prevents_send():void{$this->prepare();$f=$this->pending();$this->transport(true,false,0);DB::table('voice_contacts')->where('id',$this->contact)->update(['fields'=>'{"email":"other@example.test"}']);app(CadenceEmail::class)->run();$this->assertDatabaseHas('voice_email_followups',['status'=>'cancelled']);}
 public function test_optout_requires_signed_confirmation_and_blocks_same_address():void{$this->prepare();$f=$this->pending();$this->transport();app(CadenceEmail::class)->run();$url=URL::signedRoute('cadence.email.unsubscribe',['id'=>$f->id]);$this->get($url)->assertOk();$this->assertDatabaseCount('voice_email_optouts',0);$this->post('/email/preferences/'.$f->id)->assertForbidden();$this->post($url)->assertOk();$this->assertDatabaseCount('voice_email_optouts',1);}
 public function test_settings_lock_permissions_and_isolation():void{$this->prepare();$d=['revision'=>1,'enabled'=>true,'subject'=>'Teste','body'=>'Teste','delay_minutes'=>0];$this->putJson($this->endpoint(),$d)->assertStatus(422);DB::table('voice_campaigns')->where('id',$this->campaign)->update(['status'=>'paused']);$this->putJson($this->endpoint(),array_replace($d,['revision'=>0]))->assertStatus(409);$this->putJson($this->endpoint(),array_replace($d,['subject'=>"x\r\ny"]))->assertStatus(422);$this->putJson($this->endpoint(),array_replace($d,['body'=>'{segredo}']))->assertStatus(422);$this->admin->forceFill(['voice_role'=>'agent'])->save();$this->getJson($this->endpoint())->assertForbidden();DB::table('voice_workspaces')->insert(['id'=>2,'name'=>'Outro ambiente']);$this->admin->forceFill(['voice_role'=>'admin','voice_workspace_id'=>2])->save();$this->getJson($this->endpoint())->assertNotFound();}
 public function test_pending_email_preserves_active_run_and_exit_cancels_step():void{$this->prepare();$run=(string)Str::uuid();DB::table('voice_cadence_runs')->insert(['id'=>$run,'workspace_id'=>1,'campaign_id'=>$this->campaign,'contact_id'=>$this->contact,'number'=>1,'trigger'=>'test','policy'=>json_encode(CadenceReentry::DEFAULTS),'entered_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$this->attempt(['run_id'=>$run]);$this->attempt(['run_id'=>$run]);$r=DB::table('voice_cadence_runs')->find($run);app(CadenceReentry::class)->reconcile($r);$this->assertDatabaseHas('voice_cadence_runs',['id'=>$run,'status'=>'active']);app(CadenceReentry::class)->finish($r,'source_left');$this->assertDatabaseHas('voice_email_followups',['run_id'=>$run,'status'=>'cancelled']);}
 public function test_real_smtp_acceptance_and_dropped_ack_are_not_confused_with_delivery():void {
  foreach(['accept','drop']as $mode){
   $ready=tempnam(sys_get_temp_dir(),'smtp-ready-');$log=tempnam(sys_get_temp_dir(),'smtp-log-');$err=tempnam(sys_get_temp_dir(),'smtp-err-');
   $proc=proc_open([PHP_BINARY,base_path('tests/Fixtures/cadence-smtp.php'),$ready,$log,$mode],[0=>['pipe','r'],1=>['file',$err,'a'],2=>['file',$err,'a']],$pipes);
   try{
    for($i=0;$i<100;$i++){clearstatcache();if(filesize($ready)>0)break;usleep(20000);}
    $address=trim(file_get_contents($ready));$this->assertNotEmpty($address);
    config(['cadence_email.enabled'=>true,'cadence_email.from'=>'sender@example.test','cadence_email.reply_to'=>'reply@example.test','cadence_email.daily_limit'=>20,'mail.mailers.smtp'=>['transport'=>'smtp','scheme'=>'smtp','host'=>'127.0.0.1','port'=>(int)substr(strrchr($address,':'),1),'username'=>null,'password'=>null,'local_domain'=>'fixture.test']]);
    $transport=new CadenceEmailTransport();$this->assertTrue($transport->ready());$failed=false;
    try{$transport->send((string)Str::uuid(),'person@example.test','Teste','Texto sintético.');}catch(\Throwable){$failed=true;}
    $this->assertSame($mode==='drop',$failed);$this->assertSame("DATA\n",file_get_contents($log));
   }finally{if(is_resource($proc)){proc_terminate($proc);foreach($pipes as $pipe)if(is_resource($pipe))fclose($pipe);proc_close($proc);}foreach([$ready,$log,$err]as $f)@unlink($f);}
  }
 }

 public function test_phone_change_and_inflight_email_protect_identity_and_configuration():void {
  $this->prepare();$f=$this->pending();$this->transport(true,false,0);DB::table('voice_campaigns')->where('id',$this->campaign)->update(['status'=>'paused']);DB::table('voice_email_followups')->where('id',$f->id)->update(['status'=>'submitting']);$this->putJson($this->endpoint(),['revision'=>1,'enabled'=>false,'subject'=>'Teste','body'=>'Teste','delay_minutes'=>0])->assertStatus(409);
  DB::table('voice_email_followups')->where('id',$f->id)->update(['status'=>'pending']);DB::table('voice_campaigns')->where('id',$this->campaign)->update(['status'=>'testing']);DB::table('voice_contacts')->where('id',$this->contact)->update(['phone'=>'+5511999990002']);app(CadenceEmail::class)->run();$this->assertDatabaseHas('voice_email_followups',['id'=>$f->id,'status'=>'cancelled','submitted_at'=>null]);
 }

}
